G(7,()=>orderTask('★ Доказываем: если a ∥ b, а AK и BK — биссектрисы односторонних углов при секущей AB, то ∠AKB = 90°. Шаги перепутаны:',
 ['∠A + ∠B = 180° (односторонние углы при a ∥ b)','Биссектрисы образуют с прямыми a и b углы ½∠A и ½∠B','По свойству зигзага ∠AKB = ½∠A + ½∠B','∠AKB = ½(∠A + ∠B) = ½ · 180° = 90°'],
 {short:'Сумма 180° → половинки → зигзаг → 90°.',explain:'Начинаем со свойства параллельных (сумма односторонних 180°), затем определение биссектрисы (половинки), затем свойство зигзага для ломаной A–K–B, и в конце арифметика.',explain2:'Шаг «½(∠A + ∠B) = 90°» нельзя сделать, пока не известно, что ∠A + ∠B = 180°, — поэтому он последний.'}),{star:true});

/* =====================================================================
   WIDGET
   ===================================================================== */
function onTheory(root){const w=root.querySelector('#w-par');if(!w)return;
  w.innerHTML=`<label>Наклон секущей: <output id="wpa">60</output>°<input type="range" id="wpA" min="25" max="155" step="1" value="60"></label>
<label>Поворот прямой b: <output id="wpb">0</output>°<input type="range" id="wpB" min="-20" max="20" step="1" value="0"></label>
<div id="wpS" style="display:flex;justify-content:center"></div><div id="wpO" class="small" style="text-align:center;margin-top:4px"></div>`;
  const A=w.querySelector('#wpA'),B=w.querySelector('#wpB');
  const draw=()=>{const al=+A.value,be=+B.value;w.querySelector('#wpa').textContent=al;w.querySelector('#wpb').textContent=be;const labs={};for(let k=1;k<=8;k++)labs[k]=val8(al,k,be)+'°';
    w.querySelector('#wpS').innerHTML=par8(al,labs,{be,hl:[3,5],W:300,H:210,gap:110});const v3=val8(al,3,be),v5=val8(al,5,be),v4=val8(al,4,be);
    w.querySelector('#wpO').innerHTML=`Накрест лежащие ∠3 = ${v3}°, ∠5 = ${v5}° — ${v3===v5?'<b>равны</b>':'не равны'}. Односторонние ∠4 + ∠5 = ${v4} + ${v5} = ${v4+v5}°. ${be===0?'<span class="out">a ∥ b</span>':`<b>a и b пересекаются</b> (${v4+v5<180?'справа':'слева'} от секущей — там, где сумма односторонних меньше 180°)`}`;};
  A.oninput=B.oninput=draw;draw();}

